fn bound_shift(x:i32)->i32{let s=x.wrapping_shl(1);if s<0{s.wrapping_add(1)}else{i32::MAX}}
fn left_run(a:&[i64],k:i64,b:i64,h:i64)->(i64,i64){let m=h+1;let(mut x,mut t)=(1i64,0i64);while x<m&&k<a[(b+h-x)as usize]{t=x;x=bound_shift(x as i32)as i64;}let x=x.min(m);(h-t,h-x)}
fn right_run(a:&[i64],k:i64,b:i64,n:i64,h:i64)->(i64,i64){let(mut x,mut last, m)=(1i64,0i64,n-h);while x<m&&k>a[(b+h+x)as usize]{last=x;x=bound_shift(x as i32)as i64;}let x=x.min(m);(x+h,last+h)}
fn final_offset(a:&[i64],k:i64,b:i64,mut o:i64,mut l:i64,lt:i32)->i64{l+=1;while l<o{let mid=l+(((o-l)as u64)>>1)as i64;let value=a[(b+mid)as usize];let cmp=if k<value{-1}else if k>value{1}else{0};if cmp<lt{o=mid}else{l=mid+1}}o}
#[no_mangle]
pub extern "C" fn galloping_strategy(v:*const i64,n:usize)->i64{if v.is_null()||n<5||n>69{return -1}let a=unsafe{std::slice::from_raw_parts(v,n)};let(op,count,base,len,key)=(a[0],a[1],a[2],a[3],a[4]);if !(op==0||op==1)||count<0||count>64||n!=5+count as usize||base<0||len<0||base>count||len>count-base||key<i32::MIN as i64||key>i32::MAX as i64{return -1}let vals=&a[5..];if vals.iter().any(|x|*x<i32::MIN as i64||*x>i32::MAX as i64){return -1}if count==0{return 0}if len==0||base>=count{return -1}if vals[base as usize..(base+len)as usize].windows(2).any(|w|w[0]>w[1]){return -1}let(o,l)=if op==0{if key>vals[base as usize]{right_run(vals,key,base,len,0)}else{left_run(vals,key,base,0)}}else if key<vals[base as usize]{left_run(vals,key,base,len)}else{right_run(vals,key,base,len,0)};final_offset(vals,key,base,o,l,if op==0{1}else{0})}
